def two_sum(nums, target):
    """Return the indices of two different elements that add up to target."""
    seen = {}  # value -> index
    for i, x in enumerate(nums):
        seen[x] = i
        need = target - x
        if need in seen:
            return [seen[need], i]
    return []


def describe(nums, target):
    pair = two_sum(nums, target)
    if not pair:
        return "no pair"
    return f"indices {pair[0]} and {pair[1]}"


print(describe([3, 2, 4], 6))

