def rotate(matrix):
    """Rotate an n x n matrix 90 degrees clockwise, in place."""
    n = len(matrix)
    # step 1: transpose
    for i in range(n):
        for j in range(n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # step 2: reverse every row
    for row in matrix:
        row.reverse()


grid = [
    [1, 2],
    [3, 4],
]
rotate(grid)
print(grid)

