class RangeSum:
    """Answers sum(nums[left..right]) quickly, both ends included."""

    def __init__(self, nums):
        self.pre = [0]
        for x in nums:
            self.pre.append(self.pre[-1] + x)

    def sum_range(self, left, right):
        return self.pre[right] - self.pre[left]


def check(nums, queries):
    r = RangeSum(nums)
    return [r.sum_range(i, j) for i, j in queries]


nums = [-2, 0, 3, -5, 2, -1]
print(check(nums, [(0, 2), (2, 5), (0, 5)]))

