def first_missing_positive(nums):
    """Smallest positive integer that is not in nums, O(n) time, O(1) space."""
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n


def check(nums):
    result = first_missing_positive(list(nums))
    assert result >= 1
    return result


print(check([1, 2, 3]))

